script:
var doc = Document;
// Goal: put a door of a given type into an existing wall. Reads at top level; the host wall and the
// door are created inside one block.
// A blank project has levels already; take the lowest one rather than creating another.
Autodesk.Revit.DB.Level level = null;
foreach (Autodesk.Revit.DB.Level l in new Autodesk.Revit.DB.FilteredElementCollector(doc).OfClass(typeof(Autodesk.Revit.DB.Level))) {
  if (level == null || l.Elevation < level.Elevation) level = l;
}

// 1. Find the door type (FamilySymbol) by family and type name, from the Doors category. Names are
//    template-dependent, so fall back to the first loaded door symbol; if the project has none, the
//    family must be loaded first (Document.LoadFamily, which runs between transaction blocks).
string wantedFamily = "Single-Flush";
Autodesk.Revit.DB.FamilySymbol doorSymbol = null;
Autodesk.Revit.DB.FamilySymbol firstDoor = null;
foreach (Autodesk.Revit.DB.FamilySymbol fs in new Autodesk.Revit.DB.FilteredElementCollector(doc)
    .OfCategory(Autodesk.Revit.DB.BuiltInCategory.OST_Doors).OfClass(typeof(Autodesk.Revit.DB.FamilySymbol))) {
  if (firstDoor == null) firstDoor = fs;
  if (fs.FamilyName == wantedFamily) { doorSymbol = fs; break; }
}
bool usedFallback = doorSymbol == null;
if (doorSymbol == null) doorSymbol = firstDoor;
if (doorSymbol == null) throw new System.Exception("no door family loaded; load one with Document.LoadFamily first");

return Connector.WithTransaction(doc, () => {
  // 2. The host: a wall on the level (a real task starts with an existing wall).
  double z = level.Elevation;
  var hostWall = Autodesk.Revit.DB.Wall.Create(doc,
      Autodesk.Revit.DB.Line.CreateBound(new Autodesk.Revit.DB.XYZ(0, 0, z), new Autodesk.Revit.DB.XYZ(20, 0, z)), level.Id, false);
  doc.Regenerate();

  // 3. Activate the symbol. A FamilySymbol that has never been placed is inactive and
  //    NewFamilyInstance throws on it; Activate() is a write, so it belongs inside the block.
  bool wasActive = doorSymbol.IsActive;
  if (!doorSymbol.IsActive) { doorSymbol.Activate(); doc.Regenerate(); }

  // 4. Place the instance at a point ON the host's location line (here its midpoint). The hosted
  //    overload takes the host and the level; StructuralType.NonStructural for a door.
  var midpoint = (hostWall.Location as Autodesk.Revit.DB.LocationCurve).Curve.Evaluate(0.5, true);
  var door = doc.Create.NewFamilyInstance(midpoint, doorSymbol, hostWall, level,
      Autodesk.Revit.DB.Structure.StructuralType.NonStructural);
  doc.Regenerate();

  // 5. Verify: the door's Host is the wall, its level matches, and it sits in the Doors category.
  return new {
    doorId = door.Id.Value, family = doorSymbol.FamilyName, type = doorSymbol.Name, usedFallbackType = usedFallback,
    symbolWasAlreadyActive = wasActive,
    hostedByWall = door.Host != null && door.Host.Id == hostWall.Id,
    onLevel = door.LevelId == level.Id,
    category = door.Category == null ? null : door.Category.Name,
    hostWallId = hostWall.Id.Value
  };
});
